<?php
 namespace App\Console\Commands; use Illuminate\Console\Command; use PDO; use PDOException; class CreateDatabaseCommand extends Command { protected $signature = 'db:create
                            {--connection= : The database connection to use}
                            {--charset= : Default charset (e.g. utf8mb4)}
                            {--collation= : Default collation (e.g. utf8mb4_unicode_ci)}'; protected $description = 'Create the database defined in environment or config if it does not already exist'; public function handle() { $connection = $this->option('connection') ?: config('database.default'); $config = config("database.connections.{$connection}"); if (empty($config)) { $this->error("Koneksi database [{$connection}] tidak ditemukan dalam config/database.php."); return 1; } $driver = $config['driver'] ?? $connection; switch ($driver) { case 'mysql': case 'mariadb': return $this->createMysqlDatabase($config); case 'sqlite': return $this->createSqliteDatabase($config); case 'pgsql': return $this->createPgsqlDatabase($config); default: $this->warn("Driver database [{$driver}] belum didukung otomatis oleh command ini."); return 0; } } protected function createMysqlDatabase(array $config) { $database = $config['database'] ?? env('DB_DATABASE'); if (empty($database)) { $this->error('Nama database belum dikonfigurasi (DB_DATABASE kosong di .env).'); return 1; } $host = $config['host'] ?? '127.0.0.1'; $port = $config['port'] ?? 3306; $username = $config['username'] ?? 'root'; $password = $config['password'] ?? ''; $charset = $this->option('charset') ?: ($config['charset'] ?? 'utf8mb4'); $collation = $this->option('collation') ?: ($config['collation'] ?? 'utf8mb4_unicode_ci'); try { $dsn = "mysql:host={$host};port={$port}"; $pdo = new PDO($dsn, $username, $password, [ PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, ]); $stmt = $pdo->prepare('SELECT SCHEMA_NAME FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME = :db'); $stmt->execute(['db' => $database]); if ($stmt->fetch()) { $this->info("Database [{$database}] sudah ada di MySQL ({$host}:{$port})."); return 0; } $escapedDb = str_replace('`', '``', $database); $pdo->exec("CREATE DATABASE `{$escapedDb}` CHARACTER SET {$charset} COLLATE {$collation}"); $this->info("Database [{$database}] berhasil dibuat di MySQL ({$host}:{$port})!"); return 0; } catch (PDOException $e) { $this->error("Gagal membuat database MySQL [{$database}]: " . $e->getMessage()); $this->line('<comment>Tips: Pastikan server MySQL (Laragon/XAMPP/Docker) sudah berjalan dan kredensial di .env sudah sesuai.</comment>'); return 1; } } protected function createSqliteDatabase(array $config) { $database = $config['database'] ?? database_path('database.sqlite'); if ($database === ':memory:') { $this->info('Database SQLite berjalan di memori (:memory:). Tidak ada file yang perlu dibuat.'); return 0; } if (file_exists($database)) { $this->info("File database SQLite [{$database}] sudah ada."); return 0; } $dir = dirname($database); if (!is_dir($dir)) { mkdir($dir, 0755, true); } touch($database); $this->info("File database SQLite [{$database}] berhasil dibuat!"); return 0; } protected function createPgsqlDatabase(array $config) { $database = $config['database'] ?? env('DB_DATABASE'); if (empty($database)) { $this->error('Nama database belum dikonfigurasi (DB_DATABASE kosong di .env).'); return 1; } $host = $config['host'] ?? '127.0.0.1'; $port = $config['port'] ?? 5432; $username = $config['username'] ?? 'postgres'; $password = $config['password'] ?? ''; try { $dsn = "pgsql:host={$host};port={$port};dbname=postgres"; $pdo = new PDO($dsn, $username, $password, [ PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, ]); $stmt = $pdo->prepare('SELECT 1 FROM pg_database WHERE datname = :db'); $stmt->execute(['db' => $database]); if ($stmt->fetch()) { $this->info("Database PostgreSQL [{$database}] sudah ada."); return 0; } $escapedDb = str_replace('"', '""', $database); $pdo->exec("CREATE DATABASE \"{$escapedDb}\""); $this->info("Database PostgreSQL [{$database}] berhasil dibuat!"); return 0; } catch (PDOException $e) { $this->error("Gagal membuat database PostgreSQL [{$database}]: " . $e->getMessage()); return 1; } } } 